function draftFeedbackHTML(draft){if(!draft)return '';const meta=draftStatusPresentation(draft),missing=(draft.missing_evidence||[]).map(missingEvidenceLabel),action=nextActionLabels[draft.next_action]||(draft.next_action?'按系统建议由人工处理':'');return `<div class="notice ${meta.color}"><strong>${escapeHTML(meta.label)}</strong><p>${escapeHTML(meta.summary)}</p>${draft.reason?`<p>${escapeHTML(draft.reason)}</p>`:''}${missing.length?`<div class="section-gap"><strong>还需要</strong><ul>${missing.map(item=>`<li>${escapeHTML(item)}</li>`).join('')}</ul></div>`:''}${action?`<p class="section-gap"><strong>建议下一步：</strong>${escapeHTML(action)}</p>`:''}${citationsHTML(draft.citations)}<details class="section-gap"><summary>查看技术状态</summary><small>status: ${escapeHTML(draft.source_status||draft.status||'unknown')} · provider: ${escapeHTML(draft.provider||'unknown')}${draft.missing_evidence?.length?` · missing_evidence: ${escapeHTML(draft.missing_evidence.join(', '))}`:''}</small></details></div>`;}
function normalizeOpportunity(item){const budget_amount=canonicalBudgetAmount(item);return {...item,budget_amount,budget_currency:item?.budget_currency||'CNY',revision:Number(item?.revision||1),profile_version:Number(item?.profile_version||1),contact_state:{marketing_opt_out:Boolean(item?.contact_state?.marketing_opt_out),human_handoff:Boolean(item?.contact_state?.human_handoff??item?.human_handoff),purchased_for_opportunity:Boolean(item?.contact_state?.purchased_for_opportunity??item?.purchased)}};}
