function activePerson(c=current(),opportunity=activeOpportunity(c)){return c?.persons?.find(person=>person.person_id===opportunity?.person_id)||c?.persons?.[0]||null;}
function latestMessage(c=current()){return (c?.messages||[]).at(-1)||null;}
function latestCustomerMessage(c=current()){return [...(c?.messages||[])].reverse().find(message=>message.role==='customer'&&message.status==='received')||null;}
function contactProtection(c=current()){const opportunity=activeOpportunity(c),local=opportunity?.contact_state||{};return {marketing_opt_out:Boolean(c?.contact_preferences?.marketing_opt_out||c?.optout||local.marketing_opt_out),human_handoff:Boolean(c?.human_handoff||c?.human||local.human_handoff),purchased_for_opportunity:Boolean(local.purchased_for_opportunity)};}
