function draftIsCurrent(c,draft){if(!draft||draft.stale)return false;const now=contextStamp(c),then=draft.context_versions||{},keys=['customer_revision','opportunity_revision','profile_version','latest_message_id','latest_conversation_message_id','product_version','opportunity_id'];if(!Object.prototype.hasOwnProperty.call(then,'latest_conversation_message_id'))return false;if(v2Runtime.status==='connected'&&!Object.prototype.hasOwnProperty.call(v2Runtime.contextByOpportunity[activeOpportunity(c)?.opportunity_id]?.context_versions||{},'latest_conversation_message_id'))return false;return keys.every(key=>String(now[key]??'')===String(then[key]??''));}
