 const visible=state.customers.filter(x=>(customerFilter==='全部'||stageLabel(x.stage)===customerFilter)&&(typeof customerMatchesJoinDate!=='function'||customerMatchesJoinDate(x))),isStale=Boolean(draft?.text&&!draftIsCurrent(c,draft)),isLoading=v2Runtime.loadingOpportunityId===opportunity?.opportunity_id,draftReady=draftCanConfirm(c,draft),draftMeta=draft?draftStatusPresentation(draft):null;
